SELECT 'screwdriver' AS seed, p.asin, p.product_name, p.manufacturer, p.stock FROM product_search JOIN products p ON p.rowid=product_search.rowid WHERE product_search MATCH '"screwdriver"*' AND p.tenant='itg' LIMIT 5;
